contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take target address and arbitrary calldata and an amount of wei to forward.
    function run(address callee, bytes calldata data, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // record balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // Perform the call and observe whether it reverts
        try c.forward{value: amount}(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call: either it succeeded and c's balance increased by amount
        // or it reverted and balances are unchanged. This asserts that no stealthy partial transfer occurred.
        assert(
            (!reverted && address(c).balance == beforeC + amount && address(this).balance == beforeThis - amount)
            || (reverted && address(c).balance == beforeC && address(this).balance == beforeThis)
        );
    }

    receive() external payable {}
}

