contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes an address of a callee contract and calldata that, when called,
    // should return the caller address (via abi.encode(msg.sender)). To observe what
    // the callee sees as msg.sender, we call c.forward and then query the callee by
    // invoking a view that returns the last observed caller address. Because we cannot
    // rely on any storage in callee, we instead use a callee that simply returns
    // its msg.sender via a direct call; the test arranges calldata to perform a
    // staticcall-like behavior: we expect the callee to have an external function
    // with signature "who()" that returns (address).
    // We cannot assume anything about the callee's internals here, so instead we
    // observe the behavior by calling the callee directly (not via c) to read
    // any returned data from the forwarded call. To capture the return value of the
    // forwarded call we perform the same call directly and compare outcomes.

    // Note: Because the forwarded call uses callee.call(_data) from address(c),
    // if it succeeds, the callee's view of msg.sender during that call must be address(c).
    // We assert that whenever c.forward returns (i.e., does not revert) then a direct
    // low-level call from this contract with the same calldata returns a possibly
    // different result but the forwarded call's returned data indicates the callee
    // observed msg.sender == address(c). We extract that by arranging _data to be
    // the ABI encoding of a function that returns address (selector + empty args)
    // and then comparing the returned 32-byte word to address(c).

    // Note: The test must compile without declaring any helper contracts. It is the
    // caller's responsibility to pass a callee that implements function who() external returns (address).

    function run(address callee, bytes memory data) public payable {
        require(true);

        // We will attempt the forwarded call and record whether it reverted and what it returned.
        bool reverted;
        bytes memory retdata;
        // perform forward and capture revert/return
        try c.forward(callee, data) {
            reverted = false;
        } catch (bytes memory _err) {
            reverted = true;
        }

        // If the forwarded call succeeded (did not revert), we expect that the callee
        // observed msg.sender equal to address(c). We can observe this only if the
        // forwarded call returned an address as ABI-encoded bytes (32 bytes). So we
        // perform the same low-level call directly from this contract to obtain the
        // return data of that call when invoked by this contract. That direct call
        // will have msg.sender == address(this) and thus is only used to decode the
        // shape (length) of returned data if any.
        (bool okDirect, bytes memory directRet) = callee.call(data);

        // If forward succeeded, then the forwarded call must have executed and returned
        // whatever the callee returns; in particular, if the callee returns exactly 32 bytes
        // representing an address, those bytes should equal abi.encode(address(c)).
        // Because we cannot directly read the forwarded call's return data from c.forward,
        // we reconstruct the expectation: when forwarding succeeds, a call from address(c)
        // to callee with data `data` must, if it returns at least 32 bytes, have the first
        // 32-byte word equal to address(c) iff the callee's implementation returns msg.sender.

        // To make a general, checkable assertion: if forward did not revert AND the callee's
        // direct call returned at least 32 bytes, then the first 32 bytes returned by the
        // direct call (when invoked by this test) must not equal the encoding of address(this)
        // interpreted as an address observing msg.sender==address(this). Instead, the forwarded
        // call (when invoked by address(c)) would have returned encoding of address(c). So we assert
        // that if forward succeeded and the direct call returned 32 bytes which equal address(this),
        // then the forward must have reverted (contradiction). Rewriting to a provable invariant:
        // If forward did not revert and the direct call returned 32 bytes equal to address(this),
        // then false — but to be useful we assert that whenever forward does not revert and the
        // callee returns 32 bytes when called directly, those 32 bytes are not equal to abi.encode(address(this)).

        // Build encodings for comparison safely
        bytes32 directWord = bytes32(0);
        if (directRet.length >= 32) {
            assembly { directWord := mload(add(directRet, 32)) }
        }
        bytes32 encThis;
        assembly { encThis := shl(96, caller()) } // caller() here is msg.sender of run, not useful
        // Instead compute abi.encode(address(this)) as left-padded 32 bytes
        bytes32 encAddrThis = bytes32(uint256(uint160(address(this))));
        bytes32 encAddrC = bytes32(uint256(uint160(address(c))));

